// Compiles src/output/page/styles.css with Tailwind (scanning only the report
// page and its UI pieces) into src/output/page/styles.generated.ts, so the CLI
// and the cloud inline the stylesheet with no Tailwind and no I/O at runtime.
//
//   bun run build:css            regenerate
//   bun run build:css --check    exit 1 when the generated file is stale
import { compile, optimize } from "@tailwindcss/node";
import { Scanner } from "@tailwindcss/oxide";
import { dirname, resolve } from "node:path";

const root = resolve(import.meta.dir, "..");
const entry = resolve(root, "src/output/page/styles.css");
const target = resolve(root, "src/output/page/styles.generated.ts");

export async function buildCss(): Promise<string> {
  const source = await Bun.file(entry).text();
  const compiler = await compile(source, {
    base: dirname(entry),
    onDependency: () => {},
  });
  const scanner = new Scanner({ sources: compiler.sources.map((s) => ({ ...s })) });
  return optimize(compiler.build(scanner.scan()), { minify: true }).code;
}

export function generatedModule(css: string): string {
  return `// Generated by scripts/build-css.ts from styles.css: do not edit.\nexport const REPORT_CSS = ${JSON.stringify(css)};\n`;
}

if (import.meta.main) {
  const css = await buildCss();
  const next = generatedModule(css);
  if (process.argv.includes("--check")) {
    const current = await Bun.file(target).text();
    if (current !== next) {
      console.error("styles.generated.ts is stale: run `bun run build:css` in packages/report");
      process.exit(1);
    }
    console.log("styles.generated.ts is up to date");
  } else {
    await Bun.write(target, next);
    console.log(`styles.generated.ts: ${(css.length / 1024).toFixed(1)} KiB`);
  }
}
